diff --git a/CHANGELOG.md b/CHANGELOG.md
index cbf075a..8106b76 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -4,6 +4,10 @@ Notable changes to Pit are documented here. GitHub release notes remain the auth

 ## [Unreleased]

+### Fixed
+
+- A reply that ends with an elided-call record written as text, such as `[Pit: elided tool call: typescript · …]`, and makes no tool call no longer passes silently as a finished action (#409). Nothing ran, so Pit appends a notice for the model and the user, `▲ No tool ran`, and asks the model for one more response to make the call. A reply that repeats the mistake right after the notice gets the notice without another continuation. Elided-call records now end with `already ran; writing this text runs nothing`.
+
 ## [0.38.1] - 2026-11-17

 ### Fixed
diff --git a/src/context/boundary.ts b/src/context/boundary.ts
index 22684bd..28fde05 100644
--- a/src/context/boundary.ts
+++ b/src/context/boundary.ts
@@ -6,6 +6,7 @@ import type {
   TurnEndEvent,
 } from "@earendil-works/pi-coding-agent";

+import { imitatedCallBoundary } from "./imitated-calls.js";
 import { registerNoteRecovery, staleNoteGroups } from "./notes.js";
 import { NOTICE_LEVELS, pressureNotice } from "./notices.js";
 import type { ContextEditQueue, StagedEdit } from "./queue.js";
@@ -184,7 +185,14 @@ export function registerContextBoundary(pi: ExtensionAPI, queue: ContextEditQueu
       entries.push(...pressureNotice(ctx));
     }
     // Boundary handlers chain: keep the entries earlier handlers proposed.
-    return entries.length === 0 ? undefined : { entries: [...event.entries, ...entries] };
+    // A reply that wrote an elided-call record instead of a call ran nothing: say so (#409).
+    const imitated = imitatedCallBoundary(event, ctx);
+    if (imitated) entries.push(imitated.entry);
+    if (entries.length === 0) return undefined;
+    return {
+      entries: [...event.entries, ...entries],
+      ...(imitated?.continue ? { continue: true } : {}),
+    };
   });
   // The next request after the run follows the user's reply, often after the cache expired.
   pi.on("agent_before_settle", (event, ctx) => {
diff --git a/src/context/edits.ts b/src/context/edits.ts
index 0fe5f27..84c5ec7 100644
--- a/src/context/edits.ts
+++ b/src/context/edits.ts
@@ -15,6 +15,7 @@ import {
   type ContextItem,
   type ContextView,
   ELIDED_CALLS_PREFIX,
+  ELIDED_CALLS_RECORD,
   ELIDED_PREFIX,
   type EditableContent,
 } from "./view.js";
@@ -60,6 +61,8 @@ function callNote(view: ContextView, item: ContextItem, reason?: string): string
     ...(failed > 0 ? [`${failed} failed`] : []),
     ...(reason ? [`reason: ${reason}`] : []),
     `originals: ${[item.id, ...results.map((result) => result.id)].map((id) => `session.inspectEntry("${id}")`).join(", ")}`,
+    // Says the note records calls that ran, so a model does not write one as a call (#409).
+    ELIDED_CALLS_RECORD,
   ];
   return `${parts.join(" · ")}]`;
 }
diff --git a/src/renderers/context-entries.ts b/src/renderers/context-entries.ts
index 5147e50..6dc1d3e 100644
--- a/src/renderers/context-entries.ts
+++ b/src/renderers/context-entries.ts
@@ -6,6 +6,7 @@ import type {
 } from "@earendil-works/pi-coding-agent";
 import { Box, type Component, Text } from "@earendil-works/pi-tui";

+import { IMITATED_CALL_TYPE, type ImitatedCallDetails } from "../context/imitated-calls.js";
 import type { NoticeDetails } from "../context/notices.js";
 import { CACHE_BASIS, formatTokens, textTokens } from "../context/planning.js";
 import {
@@ -108,6 +109,26 @@ export function renderNotice(
   return new Text(lines.join("\n"), 1, 0);
 }

+export function renderImitatedCall(
+  message: CustomMessage,
+  options: { expanded: boolean },
+  theme: Theme,
+): Component {
+  const details = message.details as Partial<ImitatedCallDetails> | undefined;
+  const next =
+    details?.continued === false
+      ? "repeated after a notice; Pit did not ask again"
+      : "Pit asked the model to make the call";
+  const lines = [
+    theme.fg(
+      "warning",
+      `▲ No tool ran · the reply ended with an elided-call record, not a call · ${next}`,
+    ),
+  ];
+  if (options.expanded) lines.push(theme.fg("dim", clean(messageText(message))));
+  return new Text(lines.join("\n"), 1, 0);
+}
+
 /** Saved-function changes the system prompt does not list yet: counts, then each change. */
 export function renderCatalogUpdate(
   message: CustomMessage,
@@ -219,6 +240,7 @@ export function renderProvenance(
 export function registerContextRenderers(pi: ExtensionAPI): void {
   pi.registerMessageRenderer(NOTE_TYPE, renderNote);
   pi.registerMessageRenderer(NOTICE_TYPE, renderNotice);
+  pi.registerMessageRenderer(IMITATED_CALL_TYPE, renderImitatedCall);
   pi.registerMessageRenderer(CATALOG_UPDATE_TYPE, renderCatalogUpdate);
   pi.registerEntryRenderer(PROVENANCE_TYPE, renderProvenance);
 }

